import xml.etree.ElementTree as ET

def xml_children_as_dict(node: ET.Element) -> dict:
    """Turn the children of an XML element into a dict, keyed by tag name.

    The values are the stripped text content of the child elements.
    Only a shallow conversion is performed; child elements are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    for child in node:
        text = child.text.strip() if child.text else None
        result[child.tag] = text
    return result

